+// Brannock keeps UK time: GMT in winter, and one hour ahead (BST) in summer.
+// Crews plan their shifts on the depot wall clock, so the queue shows Brannock time.
+// Only the label changes. Every deadline is still worked out in UTC.
+const BRANNOCK_TIME_ZONE = "Europe/London";
+
+const labelFormat = new Intl.DateTimeFormat("en-GB", {
+  timeZone: BRANNOCK_TIME_ZONE,
+  weekday: "short",
+  day: "numeric",
+  month: "short",
+  hour: "2-digit",
+  minute: "2-digit",
+});
+
+// What a crew reads on the queue screen, for example "Sun 25 Oct, 14:05".
+export function brannockLabel(isoTime: string): string {
+  return labelFormat.format(new Date(isoTime));
+}
